-- SERTÃO — "Pizza Meio a Meio (qualquer sabor)"  ** NÃO EXECUTADO **
-- Precisa do OK do dono antes de rodar. Pré-requisito: migration 140
-- (price_rule/variants) já aplicada no ntb_vendas (está, desde 2026-10-01).
--
-- O que faz (só INSERT, nada é alterado/apagado):
--   * categoria nova "Monte sua Pizza" no mesmo grupo e no mesmo setor
--     (Pizzaria) da categoria Tradicionais -> imprime na Pizzaria e baixa
--     no local PIZZA, igual às pizzas de hoje;
--   * produto R$ 74,90 com grupos:
--       Tamanho  Pequena +0 / Média +10 / Grande +30
--       Sabor 1  (obrigatório) e Sabor 2 (opcional — meio a meio): os 52
--                sabores das 5 camadas; regra "vale o sabor mais caro"
--                (price_rule = 'max'); acréscimo da camada:
--                  Tradicionais/Doces +0 | Arretadas +10
--                  Danadas de Boa +30 (+20 na Grande) | Violeiras +40 (+30 na Grande)
--                => preço final = preço da camada mais cara no tamanho escolhido
--                   (bate com o cardápio impresso SVM 0001 26 A).
--       Borda    cópia da Borda da Pizza Tradicional.
--   * Omie por sabor E por tamanho (variants): Grande = "1/2 X G",
--     Média = "1/2 X M", Pequena = "X Pequena" (pizza inteira, 1 sabor) —
--     todos conferidos ativos na loja 4 do Estoque em 2026-10-01.
--     (Os produtos-camada de hoje mandam sempre o código G, em qualquer tamanho.)
--
-- Rodar:
--   ssh -i ~/.ssh/notebook_contabo_key root@185.193.66.240 \
--     "docker exec -i supabase-db psql -U supabase_admin -d ntb_vendas -v ON_ERROR_STOP=1 -1" < este_arquivo.sql
-- Desfazer: apagar o produto e a categoria "Monte sua Pizza" da loja.
-- =====================================================================

-- Gerado por gen_pizza.py — cria "Pizza Meio a Meio (qualquer sabor)" na loja 4f8a9e1a-6c3d-4b2e-9f7a-8e5c1d2b3a90.
-- Aditivo: não altera nem esconde os produtos-camada existentes.
do $$
declare
  v_store uuid := '4f8a9e1a-6c3d-4b2e-9f7a-8e5c1d2b3a90';
  v_cat uuid;
  v_prod uuid;
  v_borda jsonb;
  v_sector uuid;
  v_cat_group uuid;
  v_cat_order int;
begin
  if exists (select 1 from products where store_id = v_store and name = 'Pizza Meio a Meio (qualquer sabor)') then
    raise exception 'Produto já existe nesta loja — nada feito.';
  end if;

  -- Mesmo grupo de categorias e mesmo setor (Pizzaria) da categoria Tradicionais.
  select group_id, sector_id, "order" into v_cat_group, v_sector, v_cat_order
  from categories where store_id = v_store and name = 'Tradicionais';
  if not found then raise exception 'Categoria Tradicionais não encontrada.'; end if;

  insert into categories (store_id, name, "order", group_id, sector_id)
  values (v_store, 'Monte sua Pizza', v_cat_order, v_cat_group, v_sector)
  returning id into v_cat;

  insert into products (category_id, store_id, name, description, price, destination, ncm, "order", available)
  values (v_cat, v_store, 'Pizza Meio a Meio (qualquer sabor)', 'Escolha o tamanho e 1 ou 2 sabores de qualquer tipo: Tradicionais, Arretadas, Danadas de Boa, Violeiras do Sertão e Doces. No meio a meio vale o preço do sabor mais caro. Pizza pequena é de 1 sabor.', 74.90, 'kitchen', '19059090', 0, true)
  returning id into v_prod;

  -- Borda: cópia exata do grupo Borda da Pizza Tradicional da própria loja.
  select jsonb_build_object('name', g.name, 'type', g.type, 'required', g.required, 'price_rule', 'sum',
           'options', jsonb_agg(jsonb_build_object('name', o.name, 'price_delta', o.price_delta,
             'available', o.available, 'omie_codigo', o.omie_codigo) order by o."order"))
    into v_borda
  from product_option_groups g
  join product_options o on o.group_id = g.id
  join products p on p.id = g.product_id
  where p.store_id = v_store and p.name = 'Pizza Tradicional' and g.name = 'Borda'
  group by g.id, g.name, g.type, g.required;

