-- ---------------------------------------------------------------------
-- OPCIONAL (decisão do dono): esconder os 5 produtos-camada antigos,
-- deixando só a pizza nova. Nunca apaga (histórico de venda preservado).
-- update products set available = false
-- where store_id = '4f8a9e1a-6c3d-4b2e-9f7a-8e5c1d2b3a90'
--   and name in ('Pizza Tradicional', 'Pizza Arretada', 'Pizza Danada de Boa',
--                'Pizza Violeira do Sertão', 'Pizza Doce');
-- ---------------------------------------------------------------------

-- Conferência depois de rodar:
select g.name, g.price_rule, count(*) opcoes, count(o.variants) com_variacao
from product_option_groups g
join product_options o on o.group_id = g.id
join products p on p.id = g.product_id
where p.store_id = '4f8a9e1a-6c3d-4b2e-9f7a-8e5c1d2b3a90' and p.name = 'Pizza Meio a Meio (qualquer sabor)'
group by g.name, g.price_rule, g."order" order by g."order";
